import ast, io, pathlib, tokenize
for path in pathlib.Path('app').glob('*.py'):
    tokens = list(tokenize.generate_tokens(io.StringIO(path.read_text()).readline))
    previous = None
    gap = []
    for token in tokens:
        if token.type == tokenize.STRING:
            if previous is not None and all(item.type in {tokenize.NL, tokenize.COMMENT, tokenize.INDENT, tokenize.DEDENT} for item in gap):
                try:
                    left, right = ast.literal_eval(previous.string), ast.literal_eval(token.string)
                except Exception:
                    left = right = None
                if isinstance(left, str) and isinstance(right, str) and left and right and not left[-1].isspace() and not right[0].isspace():
                    print(f'{path}:{previous.start[0]}->{token.start[0]}: {left[-28:]!r} + {right[:28]!r}')
            previous = token
            gap = []
        elif previous is not None:
            gap.append(token)
            if token.type not in {tokenize.NL, tokenize.COMMENT, tokenize.INDENT, tokenize.DEDENT}:
                previous = None
                gap = []
