from pathlib import Path
import re
for root in (Path('EasyBusiness'), Path('backend/app')):
    vals=[]
    for p in root.rglob('*'):
        if p.suffix not in {'.swift','.py'}: continue
        for i,line in enumerate(p.read_text(errors='ignore').splitlines(),1):
            for m in re.finditer(r'"([^"\\]*(?:\\.[^"\\]*)*)"',line):
                s=m.group(1)
                if len(s)>=145 and not s.startswith(('http','easybusiness.')):
                    vals.append((len(s),str(p),i,s))
    for n,p,i,s in sorted(vals,reverse=True)[:100]: print(f'{n}\t{p}:{i}\t{s}')
